dimensions = self.page.props.dimensions
numCols = 15 if dimensions['viewport']['width'] <= 1920 else 18

return {"fixedColLength": 0, "numCols": numCols, "splitPosition": "0%", "totalCols": 0}

if len(value.data) > 1:
	rows = self.custom.selection.rows
	cols = self.custom.selection.cols
	rows.append(value.selectedRow)
	cols.append(value.selectedColumn)
else:
	rows = []
	cols = []

return {'rows': list(set(rows)), 'cols': list(set(cols))}

data = system.kanoa.utilities.convertDatasetToJSON(value)

for row in data:
	dci = row['chkItemId']
	values = []
	alerts = []
	clcl = None
	cucl = None
	for item in sorted(row):		#This section calculates lcl and ucl and color codes the values
		if not ('chkShtEventId_' in item and row[item] is not None and row['dataTypeIsNumeric']): continue
		try:
			values.append(float(row[item]))
		except:
			continue

		mean = system.math.mean(values)
		stdDev = system.math.standardDeviation(values)
		clcl = mean - (3*stdDev)
		cucl = mean + (3*stdDev)

	if len(values) == 0: min, max, mean, stdDev, sum, lcl, ucl = [None] * 7

	for item in sorted(row):		#This section calculates lcl and ucl and color codes the values
		if not ('chkShtEventId_' in item and row[item] is not None and row['dataTypeIsNumeric']): continue
		try:
			chkItemValue = float(row[item])
		except:
			continue
		if row['lsl'] and chkItemValue < row['lsl']:
			alerts.append('LSL')
			row[item] = {'value': chkItemValue, 'style':{"marginTop": '2px', "marginBottom": '2px', 'classes': 'kanoa/border', 'backgroundColor': '--kcRed-30'}}
		elif row['lcl'] and chkItemValue < row['lcl']:
			alerts.append('LCL')
			row[item] = {'value': chkItemValue, 'style':{"marginTop": '2px', "marginBottom": '2px', 'classes': 'kanoa/border', 'backgroundColor': '--kcOrange-30'}}				
		elif row['usl'] and chkItemValue > row['usl']:
			alerts.append('USL')
			row[item] = {'value': chkItemValue, 'style':{"marginTop": '2px', "marginBottom": '2px', 'classes': 'kanoa/border', 'backgroundColor': '--kcRed-30'}}
		elif row['ucl'] and chkItemValue > row['ucl']:
			alerts.append('UCL')
			row[item] = {'value': chkItemValue, 'style':{"marginTop": '2px', "marginBottom": '2px', 'classes': 'kanoa/border', 'backgroundColor': '--kcOrange-30'}}
		elif chkItemValue < clcl:
			alerts.append('cLCL')
			row[item] = {'value': chkItemValue, 'style':{"marginTop": '2px', "marginBottom": '2px', 'classes': 'kanoa/border', 'backgroundColor': '--kcYellow-30'}}
		elif chkItemValue > cucl:
			alerts.append('cUCL')
			row[item] = {'value': chkItemValue, 'style':{"marginTop": '2px', "marginBottom": '2px', 'classes': 'kanoa/border', 'backgroundColor': '--kcYellow-30'}}

	row['Calc. LCL'] = clcl
	row['Calc. UCL'] = cucl
	alerts = list(set(alerts))
	if 'LSL' in alerts or 'USL' in alerts: row['Alert'] = {"icon": "material/warning", "toolTip": "Outside of spec limits", "color": "--kcRed-50"}
	elif 'LCL' in alerts or 'UCL' in alerts: row['Alert'] = {"icon": "material/warning", "toolTip": "Outside of control limits", "color": "--kcOrange-50"}
	elif 'cLCL' in alerts or 'cUCL' in alerts: row['Alert'] = {"icon": "material/warning", "toolTip": "Outside of calculated control limits", "color": "--kcYellow-50"}
	else: row['Alert'] = {"icon": "", "toolTip": "", "color": ""}

	row['points'] = {'points': values, 'controlLimits': {'min': row['summaryMin'], 'max': row['summaryMax'], 'lsl': row['lsl'], 'lcl': row['lcl'] or clcl, 'tgt': row['tgt'], 'ucl': row['ucl'] or cucl, 'usl': row['usl'], 'mean': row['summaryAvg'], 'stdDev': row['summaryStdDev']}}

	row['chkItemName'] = {'value': row['chkItemGroupName'] + ' - ' + row['chkItemName'], 'backgroundColor': '#FFFF00'}
	row['chkItemPath'] = {'value': row['chkItemGroupName'] + ' - ' + row['chkItemPath'], 'backgroundColor': '#FFFF00'}

return data

customMethods.script:

	filters = dict(self.view.params.value.filters)
	if (filters['chkShtId'] or None) is None:
		self.view.custom.chkShtEventInfo = []
		return system.dataset.toDataSet([],[])

	filters['limit'] = self.view.custom.table.limit

	if self.view.custom.table.currentPage > 0: 
		filters['fromDate'] = self.view.custom.display.pages[self.view.custom.table.currentPage]['fromDate']
		filters['toDate'] = self.view.custom.display.pages[self.view.custom.table.currentPage]['toDate']

#	system.perspective.print("chkItemRowView - getData() called with %s"%filters)
	self.view.params.infoBar = {"showBar": True, "text": "Getting data...", "type": "INFO"}

	import java.lang	
	try:
		filters['chkShtStateNames'] = ['Approved']

		data = system.kanoa.quality.event.getChkShtEvents(filters)
		self.view.custom.chkShtEventInfo = system.kanoa.utilities.convertDatasetToJSON(system.dataset.sort(data, 'scheduledDate'))

		filters['chkShtStateIds'] = [system.kanoa.utilities.getFieldValue('chkShtStateId', system.kanoa.quality.sheet.getStates({'chkShtName': 'Approved'}))]
		data, msg = system.kanoa.quality.analysis.getChkItemEventsByRow(filters)

		if msg: 
			msg = 'Failed to get check item events. %s'%msg
			system.perspective.print(msg)
			system.perspective.sendMessage('showFailerToast', {'message': msg})

		self.view.params.infoBar = {"showBar": False, "text": "", "type": "INFO"}
	except java.lang.Exception, e:
		self.view.params.infoBar = {"showBar": False, "text": e.cause, "type": "ERROR"}

	return data
